(async () => {
  for (let k = 0; k < 300 && !(window.__luminati && window.__luminati.loadMs); k++) await new Promise((r) => setTimeout(r, 100));
  const { makeCombatFixture } = await import('/sandbox/combat_fixture.js');
  const { addObject } = await import('/src/engine/level/LevelFormat.js');
  const L = makeCombatFixture();
  L.name = 'Combat Presence';
  const find = (id) => L.objects.find((o) => o.id === id);
  // (the slimes on the dirt path, where the grass does not hide them)
  Object.assign(find('slimes'), { x: 24, z: 29, when: 'slimes-out' });
  find('goblins').unless = 'goblins-gone';
  find('cinderheart').when = 'boss-here';
  find('chest_fixture').when = 'chest-here';
  find('waystone_gate').when = 'gate-stone';
  addObject(L, 'event', 3, 37, { minX: 2.5, maxX: 4.5, minZ: 36.5, maxZ: 37.5, on: 'change', if: 'never-set', run: ['set dummy'] });
  return window.__luminati.playLocal(L, 'combat-presence');
})()

(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  for (let k = 0; k < 300 && !(window.__luminati && window.__luminati.loadMs && window.__game && window.__game.combat); k++) await sleep(100);
  await sleep(500);
  const G = window.__game;
  const g = G.game;
  const c = G.combat;
  const sys = c.system;
  const W = g.world;
  const failed = [];
  const P = window.P = {
    sleep, G, g, c, sys, W, failed, times: [],
    expect: (ok, label, detail) => { if (ok) return true; const t = `combat.presence: ${label}${detail !== undefined ? ' — ' + JSON.stringify(detail) : ''}`; failed.push(t); setTimeout(() => { throw new Error(t); }); return false; },
    programs: () => g.engine.renderer.info.programs.length,
    group: (id) => sys.enemies.filter((e) => e.groupId === id && !e.isAdd),
    look: (id) => P.group(id).map((e) => `${e.uid}:${e.alive ? 'alive' : 'dead'}:${e.sprite.visible ? 'shown' : 'hidden'}${e.dormant ? ':dormant' : ''}${e.aggro ? ':aggro' : ''}`),
    chest: () => sys.chests.list.find((x) => x.id === 'chest_fixture'),
    stone: () => sys.waystones.list.find((x) => x.id === 'waystone_gate'),
    sgroup: (id) => [...W.storyGroups.values()].find((x) => x.sample.id === id),
    collidersIn: (id) => { const sg = P.sgroup(id); return sg ? sg.colliders.filter((k) => W.tileMap.colliders.includes(k)).length : -1; },
    marker: (kind) => g._map.markers.filter((m) => m.kind === kind).map((m) => (m.hidden ? 'hidden' : 'shown')),
    painted: (id) => g._mapLevel().objects.some((o) => o.id === id),
    arena: () => sys.arenas[0],
    set: async (name, v) => { G.story.set(name, v); await sleep(700); },
  };
  const orig = sys.applyPresence.bind(sys);
  sys.applyPresence = (fn) => { const t0 = performance.now(); orig(fn); P.times.push(+(performance.now() - t0).toFixed(3)); };
  c.god(true);
  P.p0 = P.programs();
  P.atLoad = c.stats().programsAtLoad;
  const st = c.state();
  P.expect(!!g.story && W.storyGroups.size >= 2, 'the level plays with a story; chest and waystone are live story groups', W.storyGroups.size);
  P.expect(st.enemies.absent === 4 && st.enemies.total === 11, 'slimes and the boss absent at load', st.enemies);
  P.expect(P.look('slimes').every((s) => s.includes(':hidden:dormant')), 'absent slimes are hidden and dormant', P.look('slimes'));
  P.expect(!c.enemies().some((e) => e.uid.startsWith('slimes')), 'the enemies() hook leaves them out');
  P.expect(P.arena().present === false && P.marker('boss').join() === 'hidden', 'an absent boss: its arena closes nothing, no map marker', P.marker('boss'));
  P.expect(c.path(24, 21, 24, 10) !== null, 'the walk grid is open into an absent arena');
  const ch = P.chest();
  P.expect(ch.absent && ch.it.disabled && ch.marker.hidden && !P.sgroup('chest_fixture').present && P.collidersIn('chest_fixture') === 0 && !P.painted('chest_fixture'), 'an absent chest: no prompt, marker, collider or paint', { absent: ch.absent, disabled: ch.it.disabled, colliders: P.collidersIn('chest_fixture') });
  const ws = P.stone();
  P.expect(ws.absent && ws.it.disabled && P.collidersIn('waystone_gate') === 0 && !P.painted('waystone_gate') && P.marker('waystone').includes('hidden'), 'an absent waystone: no prompt, collider, paint or marker', { absent: ws.absent, markers: P.marker('waystone') });
  P.expect(P.p0 === P.atLoad, 'programs after load = programsAtLoad', { p0: P.p0, atLoad: P.atLoad });
  return JSON.stringify({ programs: P.p0, atLoad: P.atLoad, enemies: st.enemies, slimes: P.look('slimes'), boss: P.look('cinderheart'), arena: { present: P.arena().present }, bossMarker: P.marker('boss'), chest: { absent: ch.absent, disabled: ch.it.disabled, colliders: P.collidersIn('chest_fixture') }, stone: { absent: ws.absent, disabled: ws.it.disabled, markers: P.marker('waystone') }, storyGroups: W.storyGroups.size });
})()

(async () => {
  window.__game.teleport(24, 33.5);
  P.c.freezeAI(true);
  await P.sleep(1200);
  return JSON.stringify({ slimes: P.look('slimes') });
})()

(async () => {
  await P.set('slimes-out', 1);
  const st = P.c.state();
  const home = P.group('slimes').every((e) => Math.hypot(e.position.x - e.home.x, e.position.z - e.home.z) < 0.6);
  P.expect(st.enemies.absent === 1 && P.look('slimes').every((s) => s.includes(':alive:shown')) && home, 'slimes come: alive, shown, at home', { enemies: st.enemies, slimes: P.look('slimes') });
  P.expect(st.kills === 0 && st.pickups === 0, 'no reward replayed', { kills: st.kills, pickups: st.pickups });
  return JSON.stringify({ enemies: st.enemies, slimes: P.look('slimes'), programs: P.programs() });
})()

(async () => {
  const { G, c, sys } = P;
  c.freezeAI(false);
  // a clean field: every foe home and calm (the absent boss stays away), only the goblins near
  G.teleport(40.5, 27.6);
  c.reset();
  c.god(true);
  P.expect(P.look('cinderheart').every((s) => s.includes(':hidden')) && c.state().enemies.absent === 1, 'the reset hook keeps an absent group away', P.look('cinderheart'));
  for (const uid of ['boar#0', 'shaman#0', 'bats#0', 'bats#1', 'archers#0', 'archers#1']) c.kill(uid);
  await P.sleep(1200);
  c.wake('goblins#0');
  c.wake('goblins#1');
  await P.sleep(1500);
  c.press('lock');
  await P.sleep(400);
  const before = c.state();
  const lockBefore = before.player.lock;
  await P.set('goblins-gone', 1);
  const st = c.state();
  const gob = P.group('goblins');
  const onMap = sys.minimapEnemies.filter((m) => gob.some((e) => e.position.x === m.x && e.position.z === m.z)).length;
  P.expect(P.look('goblins').every((s) => s.includes(':hidden:dormant') && !s.includes(':aggro')), 'goblins taken mid-fight: hidden, dormant, no aggro', P.look('goblins'));
  P.expect(lockBefore && lockBefore.startsWith('goblins') && st.player.lock === null, 'the lock-on is dropped', { before: lockBefore, after: st.player.lock });
  P.expect(st.tokens.melee === 0 && st.tokens.ranged === 0, 'their tokens are back', st.tokens);
  P.expect(st.enemies.aggro === 0 && st.enemies.absent === 3, 'no aggro left; 3 absent', st.enemies);
  P.expect(onMap === 0 && sys.minimapEnemies.length === 0, 'off the minimap', sys.minimapEnemies.length);
  P.expect(gob.every((e) => Math.hypot(e.position.x - e.home.x, e.position.z - e.home.z) < 0.01 && e.hp === e.hpMax), 'put back home at full HP', gob.map((e) => [e.position.x, e.position.z, e.hp]));
  await P.sleep(3500);
  const st2 = c.state();
  P.expect(!st2.engaged, 'the fight ends (engaged off after the linger)', st2.engaged);
  G.teleport(24.5, 37.5);
  await P.sleep(300);
  c.freezeAI(true);
  await P.set('goblins-gone', 0);
  const st3 = c.state();
  P.expect(P.look('goblins').every((s) => s.includes(':alive:shown') && !s.includes(':aggro')) && gob.every((e) => Math.hypot(e.position.x - e.home.x, e.position.z - e.home.z) < 0.01), 'goblins back home, calm', P.look('goblins'));
  c.freezeAI(false);
  return JSON.stringify({ before: { aggro: before.enemies.aggro, engaged: before.engaged, lock: lockBefore, tokens: before.tokens }, after: { enemies: st.enemies, lock: st.player.lock, tokens: st.tokens, projectiles: sys.projectiles.count, engagedLater: st2.engaged }, back: { goblins: P.look('goblins'), enemies: st3.enemies } });
})()

(async () => {
  const { G, c } = P;
  G.teleport(24, 33.5);
  await P.sleep(300);
  c.kill('slimes#0');
  await P.sleep(1500);
  await P.set('slimes-out', 0);
  const gone = P.look('slimes');
  await P.set('slimes-out', 1);
  const back = P.look('slimes');
  P.expect(back[0].includes('slimes#0:dead:hidden') && back[1].includes(':alive:shown') && back[2].includes(':alive:shown'), 'a fallen slime stays fallen when its group comes back', back);
  await P.set('slimes-out', 0);
  const rested = c.rest('waystone_camp');
  await P.sleep(300);
  const afterRest = P.look('slimes');
  P.expect(rested && afterRest.every((s) => s.includes(':alive:hidden')), 'a rest revives the absent group but keeps it away', afterRest);
  await P.set('slimes-out', 1);
  const shown = P.look('slimes');
  P.expect(shown.every((s) => s.includes(':alive:shown')), 'all three back', shown);
  return JSON.stringify({ gone, back, afterRest, shown, enemies: c.state().enemies });
})()

(async () => {
  const { G, c, sys } = P;
  G.teleport(24, 22);
  await P.sleep(300);
  await P.set('boss-here', 1);
  const a = P.arena();
  const pathIn = c.path(24, 21, 24, 10);
  P.expect(a.present && P.marker('boss').join() === 'shown' && P.look('cinderheart').join().includes(':alive:shown'), 'the boss comes: arena, marker, kneeling boss', { marker: P.marker('boss'), boss: P.look('cinderheart') });
  P.expect(pathIn === null, 'the walk grid closes the arena again', pathIn);
  G.teleport(24, 15);
  let fight = false;
  for (let k = 0; k < 40 && !fight; k++) { await P.sleep(100); fight = !!sys._bossFight && a.active; }
  P.expect(fight, 'the boss fight starts (arena closed)');
  await P.sleep(1500);
  const during = { active: a.active, sealed: sys._pv.sealed, intro: sys._introT, engaged: c.state().engaged };
  await P.set('boss-here', 0);
  const st = c.state();
  P.expect(!a.active && !a.present && !sys._bossFight && !sys._pv.sealed && !sys.locksPlayer, 'taken mid-fight: the gate opens, the fight ends', { active: a.active, fight: !!sys._bossFight, sealed: sys._pv.sealed, locks: sys.locksPlayer });
  P.expect(P.look('cinderheart').every((s) => s.includes(':hidden')) && sys._addsOf.get(P.group('cinderheart')[0]).every((x) => sys._hidden.has(x)), 'boss and adds hidden', P.look('cinderheart'));
  P.expect(st.markers === 0 || st.markers === sys.markerCount, 'markers freed', st.markers);
  return JSON.stringify({ pathIn, during, after: { active: a.active, present: a.present, markers: st.markers, enemies: st.enemies, boss: st.boss } });
})()

(async () => {
  const { G, c, sys } = P;
  G.teleport(41.5, 36.5);
  await P.sleep(300);
  await P.set('chest-here', 1);
  const ch = P.chest();
  P.expect(!ch.absent && !ch.it.disabled && P.sgroup('chest_fixture').present && P.collidersIn('chest_fixture') > 0 && P.painted('chest_fixture'), 'the chest comes: prompt, collider, paint', { disabled: ch.it.disabled, colliders: P.collidersIn('chest_fixture') });
  await P.sleep(600);
  P.expect(ch.discovered && !ch.marker.hidden && P.marker('chest').join() === 'shown', 'discovered, on the map', P.marker('chest'));
  const opened = sys.chests.open(ch);
  await P.sleep(800);
  await P.set('chest-here', 0);
  const away = { disabled: ch.it.disabled, marker: P.marker('chest'), colliders: P.collidersIn('chest_fixture'), painted: P.painted('chest_fixture') };
  P.expect(away.disabled && away.marker.join() === 'hidden' && away.colliders === 0 && !away.painted, 'the chest goes', away);
  await P.set('chest-here', 1);
  P.expect(ch.it.disabled && ch.opened && P.marker('chest').join() === 'shown', 'an opened chest comes back offering nothing', { disabled: ch.it.disabled });
  return JSON.stringify({ opened, away, back: { disabled: ch.it.disabled, marker: P.marker('chest'), colliders: P.collidersIn('chest_fixture') }, pickups: c.state().pickups });
})()

(async () => {
  const { G, c, sys } = P;
  await P.set('gate-stone', 1);
  G.teleport(29.5, 21.7);
  await P.sleep(300);
  const ws = P.stone();
  P.expect(!ws.absent && !ws.it.disabled && P.collidersIn('waystone_gate') > 0 && P.marker('waystone').every((m) => m === 'shown'), 'the gate stone comes', { disabled: ws.it.disabled, markers: P.marker('waystone') });
  await P.sleep(800);
  const attuned = c.state().player.checkpoint;
  P.expect(attuned === 'waystone_gate', 'walking up attunes it', attuned);
  await P.set('gate-stone', 0);
  const cp = c.state().player.checkpoint;
  P.expect(ws.absent && ws.it.disabled && cp === 'spawn', 'it goes: the checkpoint falls back to the start', { cp });
  const refused = await sys.waystones.rest(ws, { instant: true });
  P.expect(refused === false, 'no rest at an absent stone');
  return JSON.stringify({ attuned, after: cp, refused, markers: P.marker('waystone') });
})()

(async () => {
  const { c, sys } = P;
  await P.set('boss-here', 1);
  const kills0 = c.state().kills;
  const xp0 = c.state().player.xp;
  sys.markGroupsCleared(['cinderheart', 'no-such-group']);
  const st = c.state();
  P.expect(st.bossDefeated && P.marker('boss').length === 0 && P.look('cinderheart').join().includes(':dead:hidden'), 'a remembered defeat: boss gone, defeated, off the map', { boss: P.look('cinderheart'), markers: P.marker('boss') });
  P.expect(st.kills === kills0 && st.player.xp === xp0, 'no kill or XP counted', { kills: st.kills, kills0, xp: st.player.xp, xp0 });
  c.rest('waystone_camp');
  await P.sleep(300);
  P.expect(sys.defeatedGroups().includes('cinderheart') && !P.group('cinderheart')[0].alive, 'a rest does not bring a defeated boss back', sys.defeatedGroups());
  const programs = P.programs();
  const stats = c.stats();
  P.expect(programs === P.p0 && stats.programs === stats.programsAtLoad, 'no program compiled by any of it', { p0: P.p0, now: programs, atLoad: stats.programsAtLoad });
  const t = P.times.slice().sort((a, b) => a - b);
  return JSON.stringify({ defeated: sys.defeatedGroups(), bossDefeated: st.bossDefeated, programs, p0: P.p0, atLoad: stats.programsAtLoad, applyPresenceMs: { n: t.length, median: t[t.length >> 1], max: t[t.length - 1] }, failed: P.failed });
})()
